package com.estoqueinteligente.report;
import com.estoqueinteligente.product.ProductResponse;
public class PurchaseSuggestionResponse{private final Long productId;private final String productName,categoryName,reason;private final Integer currentQuantity,minimumStock,suggestedQuantity;public PurchaseSuggestionResponse(ProductResponse p){productId=p.getId();productName=p.getName();categoryName=p.getCategoryName();currentQuantity=p.getCurrentQuantity();minimumStock=p.getMonthlyRequiredQuantity();suggestedQuantity=Math.max(0,p.getMonthlyRequiredQuantity()-p.getCurrentQuantity());reason=p.isCountPending()?"Item pendente de contagem.":p.getCurrentQuantity()==0?"Item sem quantidade disponível. Reposição prioritária.":"Saldo abaixo da necessidade mensal.";}public Long getProductId(){return productId;}public String getProductName(){return productName;}public String getCategoryName(){return categoryName;}public Integer getCurrentQuantity(){return currentQuantity;}public Integer getMinimumStock(){return minimumStock;}public Integer getSuggestedQuantity(){return suggestedQuantity;}public String getReason(){return reason;}}
